window.TOOLKIT = {"skills": [{"id": "idea", "icon": "✦", "title": "Idea Explorer", "level": "Explorer", "desc": "Turn your interests or a problem you notice into three realistic project ideas.", "prompt": "Act as a friendly project mentor for a middle/high school student. I care about [interest or problem]. Ask me three clarifying questions one at a time, then suggest three achievable digital project ideas. For each, explain who it helps, a simple first version, what I would learn, and a realistic challenge. Do not choose for me.", "example": "Act as a friendly project mentor for a middle/high school student. I care about helping young swimmers remember their equipment before practice. I am a ninth-grade student with basic HTML experience and one weekend to build a prototype. Ask me three clarifying questions one at a time, then suggest three achievable digital project ideas. For each, explain who it helps, a simple first version, what I would learn, and a realistic challenge. Do not choose for me."}, {"id": "prompt", "icon": "✍", "title": "Prompt Improver", "level": "Explorer", "desc": "Make a vague AI request clearer, more specific and easier to evaluate.", "prompt": "Improve this prompt for an AI assistant: [paste my draft]. First identify missing context, then ask up to three key questions. Give me an improved prompt with role, goal, background, constraints, desired output and a way to check success. Explain what changed in plain English.", "example": "Improve this prompt for an AI assistant: Make me a packing app for swimming practice. I want it to remember my list on my phone, but I have never used a database. I have two afternoons and know a little HTML. First identify missing context, then ask up to three key questions. Give me an improved prompt with role, goal, background, constraints, desired output and a way to check success. Explain what changed in plain English."}, {"id": "plan", "icon": "▤", "title": "Project Planner", "level": "Explorer", "desc": "Create a small build plan, milestones and a clear definition of done.", "prompt": "I want to build [project] for [users]. My experience level is [beginner/intermediate]. Create a one-page project brief: problem, target users, three essential features, non-goals, technology options with pros/cons, milestones, tests and completion checklist. Challenge unrealistic assumptions. Keep version one doable in [time available]. Ask before coding.", "example": "I want to build a swimming-practice packing checklist for students who forget their equipment. My experience level is beginner with basic HTML knowledge. Create a one-page project brief: problem, target users, three essential features, non-goals, technology options with pros/cons, milestones, tests and completion checklist. Challenge unrealistic assumptions. Keep version one doable in six hours over one weekend. Ask before coding."}, {"id": "design", "icon": "◈", "title": "UI Design Coach", "level": "Builder", "desc": "Plan user-friendly screens, visual hierarchy and mobile layouts.", "prompt": "Act as a UI/UX mentor. Design a simple, accessible [website/app] for [audience] that helps them [task]. First describe the main user journey, then a screen-by-screen layout, navigation, typography, colors, empty states, mobile behavior and usability checks. Give two distinct visual directions and explain tradeoffs. Do not write code yet.", "example": "Act as a UI/UX mentor. Design a simple, accessible packing-checklist web app for student swimmers using phones that helps them add equipment, mark it packed, and reset their list before each practice. First describe the main user journey, then a screen-by-screen layout, navigation, typography, colors, empty states, mobile behavior and usability checks. Give two distinct visual directions and explain tradeoffs. Do not write code yet."}, {"id": "web", "icon": "⌘", "title": "Website Starter", "level": "Builder", "desc": "Build a responsive first website with understandable code.", "prompt": "Help me build a responsive website for [topic] using HTML, CSS and JavaScript. I am [experience level]. It should include [sections] and support [interactions]. Start with a simple file plan, then implement the smallest working version. Explain each file. Include keyboard/mobile usability and tell me exactly how to run and test it locally. Avoid unnecessary dependencies.", "example": "Help me build a responsive website for a beginner-friendly swimming club information page using HTML, CSS and JavaScript. I am a beginner who understands HTML tags but has not written JavaScript. It should include an introduction, a sample weekly practice schedule, an equipment checklist, and a frequently asked questions section and support expandable FAQ answers and equipment checkboxes. Use clearly labeled sample schedules and no personal photos or real contact details. Start with a simple file plan, then implement the smallest working version. Explain each file. Include keyboard/mobile usability and tell me exactly how to run and test it locally. Avoid unnecessary dependencies."}, {"id": "app", "icon": "▣", "title": "App MVP Builder", "level": "Builder", "desc": "Translate a project brief into a working minimum viable product.", "prompt": "You are my coding coach. Here is my project brief: [paste brief]. Help me create an MVP with only the three must-have features. Propose the simplest reasonable tech stack and explain its tradeoffs. Break the build into testable steps. Implement step one only and wait for my test results before proceeding. Never assume a feature works without evidence.", "example": "You are my coding coach. Here is my project brief: Practice Pack: a browser-local packing checklist for a student swimmer. Features: add an item, mark it packed, and reset all checkboxes for the next practice. Use HTML, CSS and JavaScript, with localStorage on this device. No accounts, uploads, or personal information. I know basic HTML and have one weekend. Done means items survive refresh, empty items are rejected, and all controls work with a keyboard.. Help me create an MVP with only the three must-have features. Propose the simplest reasonable tech stack and explain its tradeoffs. Break the build into testable steps. Implement step one only and wait for my test results before proceeding. Never assume a feature works without evidence."}, {"id": "explain", "icon": "{ }", "title": "Code Explainer", "level": "Explorer", "desc": "Understand code generated by AI so you can make your own choices.", "prompt": "Explain this code to me as a [grade level] student: [paste code]. Start with what it does overall, then walk through the important parts using a simple analogy. Point out the inputs, outputs and likely failure cases. Ask me two short comprehension questions and suggest one safe change I can try myself.", "example": "Explain this code to me as a ninth-grade student: function remaining(items) { return items.filter(item => !item.packed).length; }\nconst kit = [{ name: \"Goggles\", packed: true }, { name: \"Towel\", packed: false }];\nconsole.log(remaining(kit));. Start with what it does overall, then walk through the important parts using a simple analogy. Point out the inputs, outputs and likely failure cases. Ask me two short comprehension questions and suggest one safe change I can try myself."}, {"id": "debug", "icon": "⌁", "title": "Debugging Coach", "level": "Builder", "desc": "Investigate an error systematically without rewriting the whole project.", "prompt": "Help me debug a problem without making unrelated changes. Expected behavior: [expected]. Actual behavior: [actual]. Steps to reproduce: [steps]. Exact error/output: [paste]. Relevant code: [paste]. Give the most likely causes, the smallest diagnostic test, then one focused fix. Explain why it works and how to verify it. If information is missing, ask first.", "example": "Help me debug a problem without making unrelated changes. Expected behavior: Clicking Add should append Goggles to the visible list without reloading the page. Actual behavior: the list stays empty and the console reports an error. Steps to reproduce: Save the following complete snippet as index.html, open it, open the browser console, and click Add. Exact error/output: Uncaught TypeError: Cannot read properties of null (reading 'appendChild'). Relevant code: <button id=\"add\">Add</button><ul id=\"items\"></ul><script>document.getElementById(\"add\").onclick=()=>{const li=document.createElement(\"li\");li.textContent=\"Goggles\";document.getElementById(\"item-list\").appendChild(li);};</script>. Give the most likely causes, the smallest diagnostic test, then one focused fix. Explain why it works and how to verify it. If information is missing, ask first."}, {"id": "review", "icon": "✓", "title": "Project Reviewer", "level": "Innovator", "desc": "Check function, usability, accessibility, privacy and edge cases.", "prompt": "Review my [app/website] for a student project. Goal: [goal]. Features: [features]. Code or screenshots: [paste]. Assess functionality, ease of use, mobile behavior, accessibility, privacy and security basics, and edge cases. Prioritize findings as critical/important/nice-to-have. Give reproducible tests and recommend the three highest-impact improvements. Distinguish verified issues from guesses.", "example": "Review my packing-checklist website for a student project. Goal: help students track equipment for a practice session. Features: type an item, add it to a list, and mark it packed. This prototype does not save data yet. Code or screenshots: <!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Practice Pack</title><h1>Practice Pack</h1><form id=\"form\"><label for=\"item\">New item</label><input id=\"item\"><button>Add</button></form><ul id=\"list\"></ul><script>document.getElementById(\"form\").onsubmit=e=>{e.preventDefault();const input=document.getElementById(\"item\");const li=document.createElement(\"li\");const label=document.createElement(\"label\");const box=document.createElement(\"input\");box.type=\"checkbox\";label.append(box,document.createTextNode(input.value));li.append(label);document.getElementById(\"list\").append(li);input.value=\"\";};</script></html>. Assess functionality, ease of use, mobile behavior, accessibility, privacy and security basics, and edge cases. Prioritize findings as critical/important/nice-to-have. Give reproducible tests and recommend the three highest-impact improvements. Distinguish verified issues from guesses."}, {"id": "launch", "icon": "↗", "title": "Launch & Demo Coach", "level": "Innovator", "desc": "Prepare a project for publication and explain its real impact.", "prompt": "Help me prepare [project] for a responsible launch and two-minute demo. Audience: [audience]. Create a pre-launch checklist for testing, privacy, permissions, attribution, dependency/security checks, and rollback. Then outline a demo: problem, motivation, live workflow, what I personally built, how AI helped, limitations and next steps. Do not invent test results or impact.", "example": "Help me prepare Practice Pack, a browser-local equipment checklist with add, check-off, and reset controls for a responsible launch and two-minute demo. Audience: classmates and a teacher. This is a sample demo scenario; ask me what I personally wrote, how AI helped, and which tests actually passed before drafting those claims. Create a pre-launch checklist for testing, privacy, permissions, attribution, dependency/security checks, and rollback. Then outline a demo: problem, motivation, live workflow, what I personally built, how AI helped, limitations and next steps. Do not invent test results or impact."}], "projects": {"game": {"title": "My First Mini Game", "level": "Explorer", "desc": "Build a playable, single-screen browser game such as a memory match or reaction-time challenge. Success means it starts, shows a score, can restart, and works on a phone.", "prompt": "Coach me to create a very simple browser game about [theme]. I am a beginner. Keep it to one HTML file initially. Start with the game rules and acceptance checklist. Then give runnable code and explain how I can test winning, losing, score and restart. Suggest one optional personalized feature after it works.", "example": "Coach me to create a very simple browser game about catching falling swim goggles with a basket. Move the basket with arrow keys or on-screen left/right buttons. Catch ten goggles to win; miss three to lose. Each catch scores one point and Restart resets the score and misses. I am a beginner. Keep it to one HTML file initially. Start with the game rules and acceptance checklist. Then give runnable code and explain how I can test winning, losing, score and restart. Suggest one optional personalized feature after it works."}, "website": {"title": "My Passion Website", "level": "Builder", "desc": "Build a personal or community interest website with a strong introduction, three content sections and mobile navigation.", "prompt": "Help me plan and build a responsive website about [my interest or club]. Audience: [audience]. Include a homepage introduction, three useful sections, and one working interaction. Ask about my content, propose a clean layout, then build a minimal version in HTML/CSS/JS. Provide a testing checklist and deployment options.", "example": "Help me plan and build a responsive website about a fictional school swimming club called Blue Wave. Use clearly labeled sample information instead of real meeting details. Audience: students who are curious about joining and want to know what to bring to their first practice. Include a homepage introduction, three useful sections, and one working interaction. Ask about my content, propose a clean layout, then build a minimal version in HTML/CSS/JS. Provide a testing checklist and deployment options."}, "app": {"title": "My Everyday Helper", "level": "Builder", "desc": "Identify one recurring everyday problem and create a simple tool that solves it without unnecessary features.", "prompt": "I want to make a small useful app that helps [person] with [everyday problem]. Interview me to understand the workflow. Create a short project brief with three essential features, a minimal data model, privacy considerations and test cases. Then guide me through building one feature at a time. Start with a browser-local prototype if suitable.", "example": "I want to make a small useful app that helps a student swimmer with forgetting goggles, a towel, or a water bottle before practice. The student needs to reuse a packing list, check items off, and reset it for the next session without making an account. Interview me to understand the workflow. Create a short project brief with three essential features, a minimal data model, privacy considerations and test cases. Then guide me through building one feature at a time. Start with a browser-local prototype if suitable."}}, "lessons": [{"id": "start-small", "title": "Start with a real problem", "level": "Explorer", "takeaway": "A useful first project begins with someone’s need, then grows through small prototypes and feedback.", "sourceHtml": "Source: <a href=\"https://github.com/datawhalechina/easy-vibe\" target=\"_blank\" rel=\"noopener\">Datawhale / easy-vibe</a> · Hands-on course", "points": ["Talk to a potential user before choosing features. Ask about a real task they struggled with.", "Build a small version you can show; use feedback to decide what to improve.", "Learn fundamentals when you need them. Move from prototypes to backend and advanced tools as the project demands."], "exercise": "Ask a teammate how they remember practice goals. Sketch one screen for their hardest step, then have them try it using sample data.", "done": "One user need, one working interaction, and one change based on feedback.", "prompt": "Coach me through a small project for [user] who struggles with [task]. Ask about their last real experience. Help me choose one interaction to prototype, a simple test, and a question for user feedback. Let me make the final choice.", "extra": "</div>", "example": "Coach me through a small project for a student swimmer who struggles with packing their bag before after-school practice. This is a sample user scenario, not an interview result; ask me to collect a real example before drawing conclusions. Ask about their last real experience. Help me choose one interaction to prototype, a simple test, and a question for user feedback. Let me make the final choice."}, {"id": "give-context", "title": "Give AI a map of your project", "level": "Builder", "takeaway": "Clear requirements, small tasks, and useful project context make AI coding easier to review.", "sourceHtml": "Source: <a href=\"https://github.com/automata/aicodeguide\" target=\"_blank\" rel=\"noopener\">automata / aicodeguide</a> · AI coding roadmap", "points": ["Turn a conversation about your idea into a written specification: who it serves and how it should work.", "Break the work into tasks with dependencies, so each step has what it needs.", "Keep run commands, test instructions, and project conventions in an agent-readable guide; review generated code."], "exercise": "For a club website, write a short brief and three ordered tasks. Explain which task must finish first and why.", "done": "A brief, a task checklist, and instructions another person can use to run the project.", "prompt": "Read my brief: [brief]. Identify missing information, then make a small ordered task list with a check for each task. Draft project instructions using only commands and facts I provide. Mark anything unknown. Explain the first task before writing code.", "extra": "</div>", "example": "Read my brief: Practice Pack: a browser-local packing checklist for a student swimmer. Features: add an item, mark it packed, and reset all checkboxes for the next practice. Use HTML, CSS and JavaScript, with localStorage on this device. No accounts, uploads, or personal information. I know basic HTML and have one weekend. Done means items survive refresh, empty items are rejected, and all controls work with a keyboard. Files: index.html, style.css, app.js. Run by opening index.html in a browser. There is no package manager or automated test command yet. Do not invent one.. Identify missing information, then make a small ordered task list with a check for each task. Draft project instructions using only commands and facts I provide. Mark anything unknown. Explain the first task before writing code."}, {"id": "choose-tools", "title": "Choose tools for the task", "level": "Explorer", "takeaway": "Use a tool directory to discover options. A listing is a starting point for evaluation, not proof that a tool fits your project.", "sourceHtml": "Source: <a href=\"https://github.com/filipecalegario/awesome-vibe-coding\" target=\"_blank\" rel=\"noopener\">filipecalegario / Awesome Vibe Coding</a> · Curated directory", "points": ["The directory groups browser builders, editors, command-line tools, documentation tools, and communities.", "These categories support different ways of working; start with the task you need to complete.", "Toolkit recommendation: compare a small shortlist using current official information and the same tiny experiment."], "exercise": "Choose two tools for a one-page club announcement. Compare setup, cost, code export, and data handling before trying either.", "done": "A short comparison and a reason for choosing one option, with unknowns clearly marked.", "prompt": "Help me compare [tool A] and [tool B] for [small task]. Use current official sources for cost, setup, export and data handling. Separate verified facts from unknowns. Propose the same small test for both. Do not sign me up or install anything.", "extra": "</div>", "example": "Help me compare plain HTML/CSS/JavaScript and React with Vite for a single-screen equipment checklist that runs in the browser and stores data locally; I am a beginner and have six hours. Use current official sources for cost, setup, export and data handling. Separate verified facts from unknowns. Propose the same small test for both. Do not sign me up or install anything."}, {"id": "plan-first", "title": "Turn an idea into a buildable plan", "level": "Builder", "takeaway": "Separate research, product requirements, technical choices, and implementation instructions instead of asking for an entire app at once.", "sourceHtml": "Source: <a href=\"https://github.com/KhazP/vibe-coding-prompt-template\" target=\"_blank\" rel=\"noopener\">KhazP / Vibe Coding Prompt Template</a> · Planning workflow", "points": ["Research the problem and alternatives before committing to a solution.", "Describe the minimum useful product, then choose technology that supports those requirements.", "Save each planning document so the next stage starts with agreed context."], "exercise": "Plan a student event signup prototype using fictional attendees. Limit the first version to three features and list what you are leaving out.", "done": "A short problem brief, three must-have features, a technical choice with tradeoffs, and a first-step test.", "prompt": "My idea is [idea] for [audience]. Guide me through research questions, a one-page product brief, technical options, and a first implementation task. Keep the first version to three features. Ask me to review each stage before continuing; do not invent research findings.", "extra": "</div>", "example": "My idea is a reusable equipment packing checklist for student swimmers who pack in a hurry. I have no user research yet, know basic HTML, and can spend six hours on a prototype. Guide me through research questions, a one-page product brief, technical options, and a first implementation task. Keep the first version to three features. Ask me to review each stage before continuing; do not invent research findings."}, {"id": "keep-progress", "title": "Keep control as the project grows", "level": "Builder", "takeaway": "A reviewed plan, small implementation steps, and saved progress help you keep control across AI coding sessions.", "sourceHtml": "Source: <a href=\"https://github.com/EnzeD/vibe-coding\" target=\"_blank\" rel=\"noopener\">EnzeD / vibe-coding</a> · Workflow guide by Nicolas Zullo", "points": ["Keep your design goals and technology decisions in project documents.", "Work through focused steps and test them before treating them as complete.", "Record progress and save working versions so a new session can continue from evidence."], "exercise": "Add one feature to a practice-goal tracker. Record the expected behavior, actual test result, and next step before ending the session.", "done": "One tested change, a saved working version, and a short handoff note.", "prompt": "Read [project brief] and [progress note]. Confirm the next small task, make only that change, and give me a reproducible test. Report what was actually checked and what remains uncertain. Draft a handoff note with changed files, results, and the next step.", "extra": "</div>", "example": "Read Practice Pack: a browser-local packing checklist for a student swimmer. Features: add an item, mark it packed, and reset all checkboxes for the next practice. Use HTML, CSS and JavaScript, with localStorage on this device. No accounts, uploads, or personal information. I know basic HTML and have one weekend. Done means items survive refresh, empty items are rejected, and all controls work with a keyboard. and Sample handoff: index.html has an accessible form and list; app.js adds items as text and toggles checkboxes. Manual checks recorded for this fictional scenario: adding Goggles and checking it worked. Empty input still adds a blank row. Refresh persistence is not implemented. Next task: trim input and reject blank items only. Ask me for the actual files before changing code; the sample handoff is not proof about a real repository.. Confirm the next small task, make only that change, and give me a reproducible test. Report what was actually checked and what remains uncertain. Draft a handoff note with changed files, results, and the next step."}, {"id": "reusable-skills", "title": "Turn a repeatable task into a skill", "level": "Innovator", "takeaway": "Package a useful workflow as clear reusable instructions, with supporting files only when needed.", "sourceHtml": "Source: <a href=\"https://github.com/openai/skills\" target=\"_blank\" rel=\"noopener\">OpenAI / Skills</a> · Skill examples · repository deprecated", "points": ["A skill groups instructions and optional scripts or resources around a specific task.", "Toolkit recommendation: state when to use it, what input it needs, the steps, and what a good result looks like.", "The original catalog is deprecated. Follow its links to OpenAI Plugins and current plugin-building guidance for new installations."], "exercise": "Draft a “student project demo coach” skill. Try it on two different projects and revise any instruction that produces vague results.", "done": "A reusable instruction file and two recorded trials, with original sources credited.", "prompt": "Help me draft a reusable skill for [repeatable task]. Include when to use it, required inputs, steps, output format, and success checks. Ask about missing details. Test the instructions on two examples I supply, then suggest one focused improvement.", "extra": "<p><a href=\"https://github.com/openai/plugins\" target=\"_blank\" rel=\"noopener\">Current OpenAI plugin examples</a> · <a href=\"https://developers.openai.com/plugins/build/plugins\" target=\"_blank\" rel=\"noopener\">Build a plugin</a></p></div>", "example": "Help me draft a reusable skill for turning a teacher-provided assignment into a student work checklist, without doing the assignment. Inputs are the assignment text, due date, available study time, and required deliverables. Use these two sample inputs: (1) Write a 600-word comparison of two class readings, due Friday, with three quotations; I have 30 minutes daily Monday through Thursday. (2) Prepare a three-minute science presentation about evaporation, due next Wednesday, with one diagram and two sources; I have 45 minutes Saturday and Tuesday. Keep quotations and sources as tasks to find and verify, not invented content. Include when to use it, required inputs, steps, output format, and success checks. Ask about missing details. Test the instructions on two examples I supply, then suggest one focused improvement."}]};
